(function(){
  var root=document.querySelector('[data-manga-app]');if(!root)return;
  var firebase='https://firebasestorage.googleapis.com/v0/b/poketquest-3a73d.firebasestorage.app/o/japaneseLearning%2Fmanga%2Fn2%2F';
  var stories=[
    {slug:'women-warriors',title:'Women Warriors: Words on the Naginata',rail:'Separate literary legend from historical record, then follow the white paper to its meaning.',hint:'Read from the upper right toward the lower left, following panels 1–6.',alt:'An N2 Japanese learning manga about Tomoe Gozen, Nakano Takeko and Japan’s women warriors',questions:[
      {q:'What does the manga say about Tomoe Gozen?',c:['Official records prove every detail of her life','Literature remembers her as a brave woman warrior, but her existence remains uncertain','She fought at Aizu in 1868','She was another name for Nakano Takeko'],a:1,e:'Tomoe Gozen is remembered in literature as a courageous woman warrior, but the manga carefully notes that it is unclear whether she really existed.'},
      {q:"What was written on the white paper tied to Nakano Takeko's naginata?",c:['A battlefield map','A letter to her family','A poem expressing her resolve','Instructions for using the weapon'],a:2,e:"The paper was not decoration. It carried a poem expressing Takeko's resolve and was tied to her naginata."}
    ]},
    {slug:'ramen-system',title:'Ramen Shop: Five Minutes, One Machine',rail:'Follow YUJI from panic at the ticket machine to the clue waiting at the entrance.',hint:'Read from the upper right toward the lower left, following the numbered guide.',alt:'An N2 Japanese learning manga about YUJI using a ticket machine in a Japanese ramen shop',questions:[
      {q:'Why did YUJI try not to panic at the ticket machine?',c:['The cook might get angry','He might press the wrong button','He had no money','Nobody was waiting behind him'],a:1,e:'YUJI knew that panicking could make him press the wrong button while choosing quickly.'},
      {q:'What did YUJI choose after the special ramen sold out?',c:['He left the shop','The most expensive bowl','The ramen recommended for first-time customers','Nothing at all'],a:2,e:'He remembered the sign for first-time customers and chose the recommended bowl.'}
    ]}
  ];
  var questions=stories[0].questions.concat(stories[1].questions),stateKey='japaneseLearning.manga.n2_manga.nextQuestion.v1';
  var saved=Math.max(0,Math.min(questions.length,Number(localStorage.getItem(stateKey))||0));
  var query=new URLSearchParams(location.search),index=Math.min(questions.length-1,saved),locked=false;
  if(query.get('story')==='ramen')index=Math.max(2,index);
  var reader=root.querySelector('[data-reader]'),quiz=root.querySelector('[data-quiz]'),complete=root.querySelector('[data-complete]'),image=root.querySelector('[data-manga-image]'),frame=root.querySelector('.manga-frame'),status=root.querySelector('[data-image-status]'),progress=root.querySelector('[data-progress-bar]');
  function storyIndex(){return index>=2?1:0;} function localQuestionIndex(){return index%2;} function story(){return stories[storyIndex()];}
  function setText(selector,value){var node=root.querySelector(selector);if(node)node.textContent=value;}
  function save(value){localStorage.setItem(stateKey,String(value));window.dispatchEvent(new CustomEvent('manga-progress',{detail:{courseId:'n2_manga',completedSteps:value,totalSteps:questions.length,progressPercent:value*100/questions.length}}));}
  function loadImage(lang){var item=story(),slug=item.slug.replace(/-/g,'%2D'),base=firebase+slug+'%2Fv1%2F',fallback='../../../assets/manga/n2-'+item.slug+'/';frame.classList.remove('loaded');status.textContent='Loading manga…';image.dataset.fallback='0';image.alt=item.alt;image.onload=function(){frame.classList.add('loaded');};image.onerror=function(){if(image.dataset.fallback==='0'){image.dataset.fallback='1';image.src=fallback+lang+'.jpg';return;}status.textContent='The manga could not be loaded. Please try again.';};image.src=base+lang+'.jpg?alt=media';root.querySelectorAll('[data-manga-language]').forEach(function(button){var active=button.dataset.mangaLanguage===lang;button.classList.toggle('active',active);button.setAttribute('aria-pressed',active?'true':'false');});}
  function updateStory(){var item=story();setText('[data-ui="lessonTitle"]',item.title);setText('[data-ui="quizRail"]',item.rail);setText('[data-ui="readerHint"]',item.hint);setText('.lesson-number','N2 MANGA · 0'+(storyIndex()+1));}
  function showReader(){updateStory();reader.hidden=false;quiz.hidden=true;complete.hidden=true;progress.style.width=Math.round(index*100/questions.length)+'%';loadImage('ja');reader.scrollIntoView({behavior:'smooth',block:'start'});}
  function showQuiz(){reader.hidden=true;quiz.hidden=false;complete.hidden=true;progress.style.width=Math.round(index*100/questions.length)+'%';renderQuestion();quiz.scrollIntoView({behavior:'smooth',block:'start'});}
  function renderQuestion(){locked=false;var item=questions[index];setText('[data-question-count]','Question '+(localQuestionIndex()+1)+' of 2');setText('[data-question-number]',String(localQuestionIndex()+1).padStart(2,'0'));setText('[data-question]',item.q);var feedback=root.querySelector('[data-feedback]');feedback.textContent='';feedback.className='quiz-feedback';var choices=root.querySelector('[data-choices]');choices.innerHTML='';item.c.forEach(function(label,choiceIndex){var button=document.createElement('button');button.type='button';button.className='quiz-choice';button.textContent=label;button.addEventListener('click',function(){choose(choiceIndex);});choices.appendChild(button);});}
  function choose(selected){if(locked)return;locked=true;var item=questions[index],correct=selected===item.a,buttons=root.querySelectorAll('.quiz-choice');buttons.forEach(function(button,buttonIndex){button.disabled=true;if(buttonIndex===item.a)button.classList.add('correct');});var feedback=root.querySelector('[data-feedback]');feedback.textContent=(correct?'Correct! ':'Not quite. ')+item.e;feedback.classList.add(correct?'good':'try');window.setTimeout(function(){if(!correct){renderQuestion();return;}if(index+1<questions.length){index++;save(index);if(index===2)showReader();else renderQuestion();return;}save(questions.length);quiz.hidden=true;complete.hidden=false;progress.style.width='100%';localStorage.setItem('japaneseLearning.n2Manga.collection.completed.v1','true');complete.scrollIntoView({behavior:'smooth',block:'start'});},1150);}
  root.querySelectorAll('[data-manga-language]').forEach(function(button){button.addEventListener('click',function(){loadImage(button.dataset.mangaLanguage);});});
  root.querySelector('[data-start-questions]').addEventListener('click',showQuiz);root.querySelector('[data-reread]').addEventListener('click',showReader);root.querySelector('[data-read-again]').addEventListener('click',function(){index=0;save(0);showReader();});
  if(query.get('resume')==='1'&&saved>0&&saved%2!==0)showQuiz();else showReader();
})();
